import 'package:flutter/material.dart'; import 'package:get/get.dart'; import '../controllers/sales_controller.dart';
class SalesView extends StatelessWidget { const SalesView({super.key}); @override Widget build(BuildContext context){ if(!Get.isRegistered<SalesController>()) Get.put(SalesController()); final c=Get.find<SalesController>(); return Obx(() => ListView(padding: const EdgeInsets.all(20), children: [Text('Sales Function', style: Theme.of(context).textTheme.headlineSmall), ...c.leads.map((e)=>ListTile(title: Text('${e['name']}'), subtitle: Text('${e['stage']}')))]));}}
